package com.fooddelivery.restaurant.controller;import java.util.*;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import com.fooddelivery.restaurant.entity.Restaurant;import com.fooddelivery.restaurant.service.RestaurantService;@RestController @RequestMapping("/api/restaurants")public class RestaurantController{private final RestaurantService s;public RestaurantController(RestaurantService s){this.s=s;}@PostMapping public ResponseEntity<Restaurant> save(@RequestBody Restaurant r){return ResponseEntity.status(HttpStatus.CREATED).body(s.save(r));}@GetMapping public List<Restaurant> all(){return s.all();}@GetMapping("/{id}")public Restaurant get(@PathVariable String id){return s.get(id);}}
